81	    let mut found = FxHashMap::default();
82	    // Elements of nested components, each at the place in `usages` its component's declaration was reached.
83	    let mut nested: Vec<(usize, Vec<JsxUsage>)> = Vec::new();
84	    for node in nodes.iter() {
85	        let (span, function) = match node.kind() {
86	            AstKind::Function(function) => (function.span, ComponentFn::Function(function)),
87	            AstKind::ArrowFunctionExpression(arrow) => (arrow.span, ComponentFn::Arrow(arrow)),
88	            _ => continue,
89	        };
90	        let Some(holders) = functions.get(&(span.start, span.end)) else { continue };
91	        let (facts, usages_of_nested) = Reader::new(scoping, nodes).facts_of(&function);
92	        for &key in holders {
93	            found.entry(key).or_insert_with(|| facts.clone());
94	        }
95	        // Once per function, where the function itself was reached.
96	        if let Some(&at) = reached.get(&(span.start, span.end)) {
97	            nested.push((at, usages_of_nested));
98	        }
99	    }
100	    nested.sort_by_key(|(at, _)| *at);
101	    for (at, inserted) in nested.into_iter().rev() {
102	        usages.splice(at..at, inserted);
103	    }
104	    for mapping in mappings {
105	        mapping.body = found.get(&(mapping.span_start, mapping.span_end)).cloned();
106	    }
107	    usages
108	}
