125	/// The function an expression is, through parentheses, type assertions and the first argument of wrapper calls
126	/// (`memo(forwardRef((props, ref) => …))`).
127	fn unwrap<'b, 'a>(expr: &'b Expression<'a>) -> Option<ComponentFn<'b, 'a>> {
128	    match peel_expr(expr) {
129	        Expression::FunctionExpression(function) => Some(ComponentFn::Function(function)),
130	        Expression::ArrowFunctionExpression(arrow) => Some(ComponentFn::Arrow(arrow)),
131	        Expression::CallExpression(call) => unwrap(call.arguments.first()?.as_expression()?),
132	        _ => None,
133	    }
