136	/// A span as `(start, end)`.
137	type SpanKey = (u32, u32);
138	
139	/// Finds the nodes that start and end where a mapping does and the function each holds, and collects the JSX
140	/// elements outside all of those functions.
141	///
142	/// A mapping owns exactly the function [`Reader::facts_of`] reads, never the declaration or wrapper call around it:
143	/// JSX in a wrapper's other arguments or callee (`withOptions(fn, { fallback: <Icon /> })`) is the file's.
144	struct Finder {
145	    wanted: FxHashSet<SpanKey>,
146	    /// The span of each component function, to the spans of the mappings that hold it.
147	    functions: FxHashMap<SpanKey, Vec<SpanKey>>,
148	    /// Where in the file's usages each component function was reached.
149	    reached: FxHashMap<SpanKey, usize>,
150	    /// How many component functions enclose the current node.
151	    owned: u32,
152	    usages: Vec<JsxUsage>,
153	}
154	
155	impl Finder {
156	    /// Notes the function a wanted node holds.
157	    fn record(&mut self, span: oxc_span::Span, function: Option<ComponentFn<'_, '_>>) {
158	        let key = (span.start, span.end);
159	        let Some(function) = function.filter(|_| self.wanted.contains(&key)) else { return };
160	        let function = function.span();
161	        let holders = self.functions.entry((function.start, function.end)).or_default();
162	        if !holders.contains(&key) {
163	            holders.push(key);
164	        }
165	    }
166	
167	    /// Walks a function, owning its JSX when a mapping holds it. A wrapped function is reached after the declaration
168	    /// holding it, so it has been recorded by then.
169	    fn walk_function(&mut self, span: oxc_span::Span, walk: impl FnOnce(&mut Self)) {
170	        let key = (span.start, span.end);
171	        let owned = self.functions.contains_key(&key);
172	        if owned {
173	            self.reached.entry(key).or_insert(self.usages.len());
174	        }
175	        self.owned += u32::from(owned);
176	        walk(self);
177	        self.owned -= u32::from(owned);
178	    }
179	}
