192	    fn visit_function(&mut self, it: &Function<'a>, flags: ScopeFlags) {
193	        self.record(it.span, Some(ComponentFn::Function(it)));
194	        self.walk_function(it.span, |finder| walk::walk_function(finder, it, flags));
195	    }
