210	fn usage_of(it: &JSXOpeningElement<'_>) -> JsxUsage {
211	    let attributes = it
212	        .attributes
213	        .iter()
214	        .map(|attribute| match attribute {
215	            JSXAttributeItem::Attribute(attribute) => JsxUsageAttribute::Named(attribute_name(&attribute.name)),
216	            JSXAttributeItem::SpreadAttribute(_) => JsxUsageAttribute::Spread,
217	        })
218	        .collect();
219	    JsxUsage { tag: tag_of(&it.name), attributes }
220	}
