222	/// Reads one component function against the file's semantic model.
223	struct Reader<'s, 'a> {
224	    scoping: &'s Scoping,
225	    nodes: &'s AstNodes<'a>,
226	    facts: BodyFacts,
227	    /// Each read with its source position. References are classified symbol by symbol (a rest binding's after every
228	    /// one of the props object's), so the order of `facts.reads` is made from the positions once all are classified.
229	    reads: Vec<(u32, String)>,
230	    /// Each rest binding with its source position, ordered into `facts.rests` the same way.
231	    rests: Vec<(u32, String)>,
232	    /// The props object's symbols: the first parameter, and each rest binding taken from it.
233	    whole: FxHashMap<SymbolId, SpreadOf>,
234	    /// The symbols still to classify the references of.
235	    queue: VecDeque<SymbolId>,
236	    /// The destructured locals that hold one prop's value unchanged: no default, never written.
237	    locals: FxHashMap<SymbolId, String>,
238	}
239	
240	impl<'s, 'a> Reader<'s, 'a> {
241	    fn new(scoping: &'s Scoping, nodes: &'s AstNodes<'a>) -> Self {
242	        Self {
243	            scoping,
244	            nodes,
245	            facts: BodyFacts::default(),
246	            reads: Vec::new(),
247	            rests: Vec::new(),
248	            whole: FxHashMap::default(),
249	            queue: VecDeque::new(),
250	            locals: FxHashMap::default(),
251	        }
252	    }
253	
254	    fn facts_of(mut self, function: &ComponentFn<'_, 'a>) -> (BodyFacts, Vec<JsxUsage>) {
255	        let params = match function {
256	            ComponentFn::Function(function) => &*function.params,
257	            ComponentFn::Arrow(arrow) => &*arrow.params,
258	        };
259	        if let Some(first) = params.items.first() {
260	            self.props_param(&first.pattern);
261	        }
262	        while let Some(symbol) = self.queue.pop_front() {
263	            for reference in self.scoping.get_resolved_references(symbol) {
264	                self.classify(reference.node_id());
265	            }
266	        }
267	        // A key's first read is its earliest in the source.
268	        self.reads.sort_by_key(|&(at, _)| at);
269	        let mut seen = FxHashSet::default();
270	        for (_, key) in std::mem::take(&mut self.reads) {
271	            if seen.insert(key.clone()) {
272	                self.facts.reads.push(key);
273	            }
274	        }
275	        self.rests.sort_by_key(|&(at, _)| at);
276	        self.facts.rests = std::mem::take(&mut self.rests).into_iter().map(|(_, name)| name).collect();
277	        let mut elements = Elements {
278	            reader: &self,
279	            tags: FxHashSet::default(),
280	            nested_spans: FxHashSet::default(),
281	            nested: 0,
282	            elements: Vec::new(),
283	            nested_usages: Vec::new(),
284	        };
285	        // The parameters too: a default or a computed key can hold JSX (`{ icon = <Icon /> }`).
286	        match function {
287	            ComponentFn::Function(function) => {
288	                elements.tags = tag_symbols(self.scoping, |tags| {
289	                    tags.visit_formal_parameters(&function.params);
290	                    if let Some(body) = &function.body {
291	                        tags.visit_function_body(body);
292	                    }
293	                });
294	                elements.visit_formal_parameters(&function.params);
295	                if let Some(body) = &function.body {
296	                    elements.visit_function_body(body);
297	                }
298	            }
299	            ComponentFn::Arrow(arrow) => {
300	                elements.tags = tag_symbols(self.scoping, |tags| {
301	                    tags.visit_formal_parameters(&arrow.params);
302	                    tags.visit_arrow_function_body(&arrow.body);
303	                });
304	                elements.visit_formal_parameters(&arrow.params);
305	                elements.visit_arrow_function_body(&arrow.body);
306	            }
307	        }
308	        let (found, nested_usages) = (elements.elements, elements.nested_usages);
309	        self.facts.elements = found;
310	        (self.facts, nested_usages)
311	    }
312	
313	    fn props_param(&mut self, pattern: &BindingPattern<'_>) {
314	        match pattern {
315	            BindingPattern::BindingIdentifier(id) => {
316	                if let Some(symbol) = id.symbol_id.get() {
317	                    self.track(symbol, SpreadOf::Props);
318	                }
319	            }
320	            // `function C({ a } = {})`.
321	            BindingPattern::AssignmentPattern(assignment) => self.props_param(&assignment.left),
322	            BindingPattern::ObjectPattern(object) => self.destructure(object),
323	            // An array pattern reads indices of the props object, which says nothing about its keys.
324	            BindingPattern::ArrayPattern(_) => self.facts.handed_on = true,
325	        }
326	    }
327	
328	    fn track(&mut self, symbol: SymbolId, whole: SpreadOf) {
329	        if self.whole.insert(symbol, whole).is_none() {
330	            self.queue.push_back(symbol);
331	        }
332	    }
333	
334	    fn read(&mut self, at: oxc_span::Span, prop: String) {
335	        self.reads.push((at.start, prop));
336	    }
337	
338	    /// An object pattern taken from the props object: each static key is read, a plain name bound to a key that is
339	    /// never written holds that prop, and a rest binding is the props object again.
340	    fn destructure(&mut self, object: &ObjectPattern<'_>) {
341	        for property in &object.properties {
342	            let Some(key) = property.key.static_name().map(|key| js_text::property_name(&key)) else {
343	                // `{ [k]: v }` reads a key the syntax does not name.
344	                self.facts.handed_on = true;
345	                continue;
346	            };
347	            if let BindingPattern::BindingIdentifier(id) = &property.value
348	                && let Some(symbol) = id.symbol_id.get()
349	                && !self.scoping.symbol_is_mutated(symbol)
350	                // `var a` or `function a` beside `{ a }` is the same symbol, given another value.
351	                && self.scoping.symbol_redeclarations(symbol).is_empty()
352	            {
353	                self.locals.insert(symbol, key.clone());
354	            }
355	            self.read(property.span, key);
356	        }
357	        if let Some(rest) = &object.rest {
358	            match &rest.argument {
359	                BindingPattern::BindingIdentifier(id) => {
360	                    self.rests.push((rest.span.start, id.name.to_string()));
361	                    if let Some(symbol) = id.symbol_id.get() {
362	                        self.track(symbol, SpreadOf::Rest);
363	                    }
364	                }
365	                _ => self.facts.handed_on = true,
366	            }
367	        }
368	    }
369	
370	    /// The nearest ancestor of `node` that is not a TypeScript assertion or parentheses, and the span of the child
371	    /// of it the walk came from.
372	    fn through_wrappers(&self, node: NodeId) -> (NodeId, oxc_span::Span) {
373	        let (mut child, mut parent) = (self.nodes.kind(node).span(), self.nodes.parent_id(node));
374	        while matches!(
375	            self.nodes.kind(parent),
376	            AstKind::TSAsExpression(_)
377	                | AstKind::TSSatisfiesExpression(_)
378	                | AstKind::TSNonNullExpression(_)
379	                | AstKind::TSTypeAssertion(_)
380	                | AstKind::TSInstantiationExpression(_)
381	                | AstKind::ParenthesizedExpression(_)
382	        ) {
383	            child = self.nodes.kind(parent).span();
384	            parent = self.nodes.parent_id(parent);
385	        }
386	        (parent, child)
387	    }
388	
389	    /// Classifies one reference to the props object; any use not named here hands it on.
390	    fn classify(&mut self, reference: NodeId) {
391	        let (parent, child) = self.through_wrappers(reference);
392	        let read = match self.nodes.kind(parent) {
393	            AstKind::StaticMemberExpression(member) if member.object.span() == child => {
394	                Some(member.property.name.to_string())
395	            }
396	            AstKind::ComputedMemberExpression(member) if member.object.span() == child => match &member.expression {
397	                Expression::StringLiteral(key) => Some(js_text::lossy(key.value).into_owned()),
398	                _ => None,
399	            },
400	            AstKind::JSXMemberExpression(member) => Some(member.property.name.to_string()),
401	            AstKind::VariableDeclarator(declarator)
402	                if declarator.init.as_ref().is_some_and(|init| init.span() == child) =>
403	            {
404	                match &declarator.id {
405	                    BindingPattern::ObjectPattern(object) => self.destructure(object),
406	                    _ => self.facts.handed_on = true,
407	                }
408	                return;
409	            }
410	            AstKind::AssignmentExpression(assignment) if assignment.right.span() == child => {
411	                match &assignment.left {
412	                    AssignmentTarget::ObjectAssignmentTarget(object) if object.rest.is_none() => {
413	                        for property in &object.properties {
414	                            match property {
415	                                AssignmentTargetProperty::AssignmentTargetPropertyIdentifier(property) => {
416	                                    self.read(property.span, property.binding.name.to_string());
417	                                }
418	                                AssignmentTargetProperty::AssignmentTargetPropertyProperty(property) => {
419	                                    match property.name.static_name() {
420	                                        Some(key) => self.read(property.span, js_text::property_name(&key)),
421	                                        None => self.facts.handed_on = true,
422	                                    }
423	                                }
424	                            }
425	                        }
426	                    }
427	                    _ => self.facts.handed_on = true,
428	                }
429	                return;
430	            }
431	            AstKind::JSXSpreadAttribute(_) => {
432	                // Spreading the whole props object passes every prop on; a rest binding's spread is recorded only.
433	                if self.is_props(reference) {
434	                    self.facts.handed_on = true;
435	                }
436	                return;
437	            }
438	            _ => None,
439	        };
440	        let is_jsx_tag = matches!(self.nodes.kind(parent), AstKind::JSXMemberExpression(_));
441	        match read {
442	            Some(key) if is_jsx_tag || self.is_read(parent) => self.read(self.nodes.kind(reference).span(), key),
443	            Some(_) | None => self.facts.handed_on = true,
444	        }
445	    }
446	
447	    /// Whether the reference at `node` is to the first parameter itself rather than a rest binding.
448	    fn is_props(&self, node: NodeId) -> bool {
449	        let AstKind::IdentifierReference(id) = self.nodes.kind(node) else { return false };
450	        self.symbol_of(id).and_then(|symbol| self.whole.get(&symbol)) == Some(&SpreadOf::Props)
451	    }
452	
453	    /// Whether a member expression is only read: not called with its object as `this`, written, deleted or
454	    /// destructured into.
455	    fn is_read(&self, member: NodeId) -> bool {
456	        let (parent, child) = self.through_wrappers(member);
457	        let (parent, child) = match self.nodes.kind(parent) {
458	            // `props?.x`: the chain is what is called, written or deleted (`delete props?.x`, `(props?.f)()`).
459	            AstKind::ChainExpression(_) => self.through_wrappers(parent),
460	            _ => (parent, child),
461	        };
462	        match self.nodes.kind(parent) {
463	            AstKind::CallExpression(call) => call.callee.span() != child,
464	            AstKind::TaggedTemplateExpression(tagged) => tagged.tag.span() != child,
465	            AstKind::AssignmentExpression(assignment) => assignment.left.span() != child,
466	            AstKind::UnaryExpression(unary) => unary.operator != UnaryOperator::Delete,
467	            AstKind::ForInStatement(each) => each.left.span() != child,
468	            AstKind::ForOfStatement(each) => each.left.span() != child,
469	            AstKind::UpdateExpression(_)
470	            | AstKind::ArrayAssignmentTarget(_)
471	            | AstKind::ObjectAssignmentTarget(_)
472	            | AstKind::AssignmentTargetRest(_)
473	            | AstKind::AssignmentTargetWithDefault(_)
474	            | AstKind::AssignmentTargetPropertyProperty(_) => false,
475	            _ => true,
476	        }
477	    }
478	
479	    fn symbol_of(&self, id: &IdentifierReference<'_>) -> Option<SymbolId> {
480	        id.reference_id.get().and_then(|reference| self.scoping.get_reference(reference).symbol_id())
481	    }
482	
483	    fn whole_expr(&self, expr: &Expression<'_>) -> Option<SpreadOf> {
484	        match peel_expr(expr) {
485	            Expression::Identifier(id) => self.symbol_of(id).and_then(|symbol| self.whole.get(&symbol).copied()),
486	            _ => None,
487	        }
488	    }
