490	    /// The prop an attribute's value is, when it is exactly one: an unchanged destructured name, `props.x`, `rest.x`.
491	    fn value_prop(&self, value: Option<&JSXAttributeValue<'_>>) -> Option<String> {
492	        let Some(JSXAttributeValue::ExpressionContainer(container)) = value else { return None };
493	        let (object, key) = match peel_expr(container.expression.as_expression()?) {
494	            Expression::Identifier(id) => {
495	                return self.symbol_of(id).and_then(|symbol| self.locals.get(&symbol).cloned());
496	            }
497	            Expression::StaticMemberExpression(member) => (&member.object, member.property.name.to_string()),
498	            Expression::ComputedMemberExpression(member) => match &member.expression {
499	                Expression::StringLiteral(key) => (&member.object, js_text::lossy(key.value).into_owned()),
500	                _ => return None,
501	            },
502	            Expression::ChainExpression(chain) => match &chain.expression {
503	                ChainElement::StaticMemberExpression(member) => (&member.object, member.property.name.to_string()),
504	                _ => return None,
505	            },
506	            _ => return None,
507	        };
508	        self.whole_expr(object).map(|_| key)
509	    }
510	}
