596	    fn visit_jsx_opening_element(&mut self, it: &JSXOpeningElement<'a>) {
597	        if self.nested > 0 {
598	            self.nested_usages.push(usage_of(it));
599	        } else {
600	            let attributes = it
601	                .attributes
